const maxX=state.view==='day'?24:new Date(Number(state.date.slice(0,4)),Number(state.date.slice(5,7)),0).getDate();upper=Math.ceil(upper/20)*20;const x=a=>L+(a-1)/(maxX-1)*w,y=a=>T+h-a/upper*h;const bounds=P[state.code].bounds;let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">`;
svg+=`<text x="18" y="${T+h/2}" transform="rotate(-90 18 ${T+h/2})" text-anchor="middle" fill="#687e77" font-size="13">Concentrazione (µg/m³)</text><text x="${L+w/2}" y="${H-12}" text-anchor="middle" fill="#687e77" font-size="13">${state.view==='day'?'Ora del giorno':('Giorno del mese · '+new Date(state.date+'T12:00:00').toLocaleDateString(uiLocale(),{month:'long',year:'numeric'}))}</text>`;let start=0;[...bounds,upper].forEach((end,i)=>{let top=Math.min(end,upper);if(start<upper&&top>start)svg+=`<rect x="${L}" y="${y(top)}" width="${w}" height="${y(start)-y(top)}" fill="${bandColors[i]}"/>`;start=end});
for(let i=0;i<=4;i++){let v=upper*i/4;svg+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#dce5de" stroke-width=".6"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#687e77">${v}</text>`}
const ticks=state.view==='day'?[1,4,8,12,16,20,24]:[1,5,10,15,20,25,maxX];ticks.forEach(a=>svg+=`<text x="${x(a)}" y="${H-B+24}" text-anchor="middle" fill="#687e77" font-size="11">${state.view==='day'?String(a).padStart(2,'0')+':00':a}</text>`);
