 const valueAt=(day,h)=>{const date=new Date(day).toISOString().slice(0,10);const v=D.records[sid]?.[date]?.[code===10?dailyCode:code]?.[h-1];return Number.isFinite(v)&&v>=0?v:null};
 if(code===8||code===9){for(let d=0;d<=daysBefore;d++)for(let h=1;h<=(d===daysBefore?hour:24);h++){const v=valueAt(start+d*dayMs,h);if(v===null)continue;valid++;sum+=v;if(v>200)above++;}return{valid,above,within:valid-above,missing:expectedHours-valid,total:expectedHours,mean:valid?sum/valid:null,fullYear,unit:'ore'};}
