  const day=start+d*dayMs;
  if(code===10){const values=Array.from({length:24},(_,i)=>valueAt(day,i+1)).filter(v=>v!==null);if(values.length<18)continue;valid++;if(values.reduce((a,b)=>a+b,0)/values.length>dailyThreshold)above++;}
  else if(code===14){const avgs=[];for(let end=1;end<=24;end++){const values=[];for(let delta=0;delta<8;delta++){const index=end-1-delta;const v=valueAt(index<0?day-dayMs:day,index<0?index+25:index+1);if(v!==null)values.push(v)}if(values.length>=6)avgs.push(values.reduce((a,b)=>a+b,0)/values.length);}if(avgs.length<18)continue;valid++;if(Math.max(...avgs)>120)above++;}
