 const values=[s.within,s.above,s.missing],palette=['#4c8072','#bf665b','#c8cecb'],labels=['Entro la soglia','Sopra la soglia','Dati insufficienti'];let offset=0;const segments=values.map((n,i)=>{const len=s.total?n/s.total*100:0;const svg=`<circle cx="70" cy="70" r="53" pathLength="100" fill="none" stroke="${palette[i]}" stroke-width="19" stroke-dasharray="${len} ${100-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 70 70)"/>`;offset+=len;return svg}).join('');
 $('annualBody').innerHTML=`<p class="annualThreshold">${cfg.threshold}</p><div class="annualLayout"><svg class="annualDonut" viewBox="0 0 140 140" role="img" aria-label="${s.above} ${s.unit} sopra soglia, ${s.within} entro soglia, ${s.missing} con dati insufficienti su ${s.total}"><circle cx="70" cy="70" r="53" fill="none" stroke="#eef1ed" stroke-width="19"/>${segments}<text x="70" y="70" dominant-baseline="middle" text-anchor="middle" fill="#163d35" font-size="23" font-weight="700">${s.valid&&s.total?fmt(s.above/s.total*100)+'%':'—'}</text></svg><div class="annualLegend">${labels.map((label,i)=>`<div><i style="background:${palette[i]}"></i><span>${label}<small>${values[i].toLocaleString(uiLocale())} ${s.unit} · ${s.total?fmt(values[i]/s.total*100):0}%</small></span></div>`).join('')}<p>Percentuali su ${s.total.toLocaleString(uiLocale())} ${s.unit} attesi nel periodo, compresi quelli non valutabili.</p></div></div><p><strong>${cfg.reference}</strong></p><p>${cfg.method}</p>${s.excludedCurrent?'<p>L’ultimo giorno del periodo è incompleto ed è escluso dal grafico.</p>':''}<p>${s.valid===0?'Nessun intervallo valutabile per questo inquinante: il valore zero non indica assenza di superamenti.':partial||preliminary?'Conteggio provvisorio: periodo incompleto o misure preliminari.':'Conteggio sul periodo annuale, con la copertura indicata. Eventuali intervalli mancanti possono nascondere altri superamenti.'}</p>`;
