function render(){if(followLatest)selectLatestAvailable();updateSourceInfo();$('learnLink').textContent='Scopri '+P[state.code].name+' ↗';$('learnLink').href='#learn-'+state.code;let s=station(),r=row(),q=quality();$('stationName').textContent=s.name;$('stationType').textContent=s.type+' · rete comunale di Madrid';let date=new Date(state.date+'T12:00:00').toLocaleDateString(uiLocale(),{day:'numeric',month:'long',year:'numeric'});const hs=String(state.hour).padStart(2,'0')+':00';$('latest').textContent=q.count?`${followLatest?'Ultima rilevazione disponibile':'Rilevazione selezionata'}: ${date}, ore ${hs}`:`Nessuna misura valida: ${date}, ore ${hs}`;$('readingSub').textContent=`Media oraria ${String(state.hour-1).padStart(2,'0')}:00–${hs}`;
$('qualityLabel').textContent=q.level===null?'Non disponibile':q.complete?names[q.level]:q.level>=3?names[q.level]+' · parziale':'Dati insufficienti';$('dominant').innerHTML=q.level===null||!q.complete&&q.level<3?'—':q.dominant.map(name=>{const c=order.find(c=>P[c].name===name);return `<a href="#learn-${c}" data-guide="${c}" aria-label="Scopri ${name}">${name}</a>`}).join(', ');document.querySelector('.quality').style.background=q.level===null||!q.complete?'#edf0eb':colors[q.level]+'25';$('coverage').innerHTML=`${q.count} inquinanti disponibili su 4 (SO₂ escluso).<br>${q.complete?'Copertura minima EEA soddisfatta.':'Copertura minima EEA non soddisfatta: nessun giudizio completo.'}`;
$('pollutants').innerHTML=order.map(c=>{let v=r[c]?.[state.hour-1]??null,k=cat(v,c);return`<button class="pollutant ${c===state.code?'active':''}" style="--cat:${k===null?'#bfc8c0':colors[k]}" data-code="${c}" aria-pressed="${c===state.code}" aria-label="${P[c].name}: ${v===null?'non disponibile':v+' microgrammi per metro cubo'}"><span>${P[c].name}</span><strong>${v===null?'—':v.toLocaleString(uiLocale(),{maximumFractionDigits:1})}</strong><small>µg/m³<br>${k===null?'non disponibile':names[k]}</small></button>`}).join('');document.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>{state.code=Number(b.dataset.code);render()});
$('chartTitle').textContent=P[state.code].name+(state.view==='day'?' · andamento della giornata':' · andamento del mese');$('chartSubtitle').textContent=state.view==='day'?'Misure fino all’ora selezionata · fasce EEA orarie':'Massimo orario di ciascun giorno · fino alla data selezionata';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));document.querySelector('.profileControls').style.display='flex';$('comparisonMode').value=!state.profile?'none':state.shared?'shared':'station';const p=chooseProfile();drawChart(p);const bounds=P[state.code].bounds;$('bandGuide').innerHTML=`<div class="eeaGuide"><strong>Bande di sfondo del grafico: categorie EEA per ${P[state.code].name}</strong><div class="bandKeys">${names.map((name,i)=>`<span><i style="background:${bandColors[i]};border-color:${colors[i]}"></i><b>${name}</b><small>${i===0?'0–'+bounds[0]:i===5?'oltre '+bounds[4]:'oltre '+bounds[i-1]+' fino a '+bounds[i]} µg/m³</small></span>`).join('')}</div><p>Confronta l’altezza della curva con queste fasce. Sono categorie orarie, non limiti di legge.</p></div>${state.profile?`<div class="variabilityGuide"><strong>Fascia verde attorno al tratteggio: variabilità storica</strong><p>La linea tratteggiata mostra l’andamento tipico delle giornate simili del passato. La fascia verde è stretta quando i valori erano simili tra loro, larga quando erano più diversi. La sua larghezza mostra quindi quanto variavano i valori storici.</p><p>Il confronto riguarda ${state.view==='day'?'la stessa ora del giorno':'i picchi giornalieri'}.</p><p>È una distribuzione storica, non un intervallo di previsione o di confidenza.</p></div>`:''}`;$('profileLegend').style.display=$('bandLegend').style.display=state.view==='month'&&state.profile||p?.g?'flex':'none';document.querySelector('.chartLegend span:first-child').innerHTML=`<i class="solid"></i>${state.view==='day'?'Misure della giornata':'Massimi orari giornalieri'}`;if(state.view==='month'){ $('profileLegend').innerHTML='<i class="dashed"></i>Andamento atteso dal passato';$('profileInfo').textContent=state.profile?'Per ogni giorno viene associato un gruppo usando solo le misure disponibili fino alla selezione. Tratteggio: mediana dei massimi orari delle giornate storiche del gruppo. Fascia verde: 25°–75° percentile dei massimi. Riferimento della centralina, oppure condiviso se necessario. I giorni senza un gruppo utilizzabile restano vuoti. Il giorno selezionato può essere incompleto. Non è un clustering dei mesi né una previsione.':'Confronto storico disattivato.';}else if(p?.g){$('profileLegend').innerHTML=`<i class="dashed"></i>Andamento atteso dal passato`;$('profileInfo').innerHTML=`<strong>${p.source==='condiviso'?'Riferimento condiviso tra centraline':'Riferimento della centralina'}</strong> · stesso mese, ${D.history}. Gruppo ${p.i+1}, ${p.g.n} giornate${p.g.stationDays?', '+p.g.stationDays+' profili giornata-centralina':''}. Mediana delle concentrazioni originali e fascia 25°–75° percentile. Associazione sulle sole ore osservate. <strong>Confronto storico, non previsione.</strong>`}else $('profileInfo').textContent=state.view==='month'?'Le fasce colorate classificano i massimi orari, non le medie giornaliere.':p?.unavailable||(!state.profile?'Confronto storico disattivato.':'Nessun gruppo storico con copertura sufficiente per questo mese e inquinante.');if(state.profile&&Number(state.date.slice(0,4))<=2025)$('profileInfo').innerHTML+=' <strong>La giornata selezionata appartiene al periodo usato per costruire il profilo.</strong>';monthSummary();annualSummary();if(map){D.stations.forEach(st=>{let z=quality(st.id);markers[st.id].setStyle({fillColor:mapColor(st.id),fillOpacity:z.complete?.95:.45,color:st.id===state.station?'#153e34':'#fff',weight:st.id===state.station?4:2,radius:st.id===state.station?11:8})})}else drawFallback();localize();}
const LIVE_URL='https://ciudadesabiertas.madrid.es/dynamicAPI/API/query/calair_tiemporeal.json?pageSize=4500';
const RECENT_URL='https://ciudadesabiertas.madrid.es/dynamicAPI/API/query/calair_tiemporeal_ult.json?pageSize=4500';
function availableDates(){return [...new Set(Object.values(D.records).flatMap(r=>Object.keys(r)))].sort()}
function parseRecent(payload){
 if(!payload||!Array.isArray(payload.records)||Number(payload.status)!==200)throw Error('Risposta comunale non valida');
 if(Number(payload.totalRecords)>payload.records.length)throw Error('Risposta incompleta: pagine mancanti');
 const records={},known=new Set(D.stations.map(s=>s.id));let accepted=0;
 for(const raw of payload.records){const r=Object.fromEntries(Object.entries(raw).map(([k,v])=>[k.toUpperCase(),v]));if(Number(r.MUNICIPIO)!==79||!order.includes(Number(r.MAGNITUD)))continue;
 const sid=String(r.PUNTO_MUESTREO||'').split('_')[0];if(!known.has(sid))continue;
 const date=`${String(r.ANO).padStart(4,'0')}-${String(r.MES).padStart(2,'0')}-${String(r.DIA).padStart(2,'0')}`;
 if(!/^20\d\d-\d\d-\d\d$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)continue;
 const values=Array.from({length:24},(_,i)=>{const h=String(i+1).padStart(2,'0'),rawValue=r['H'+h];const v=rawValue==null||String(rawValue).trim()===''?NaN:Number(String(rawValue).replace(',','.'));return String(r['V'+h]).trim().toUpperCase()==='V'&&Number.isFinite(v)&&v>=0?v:null});
 (records[sid]??={})[date]??={};records[sid][date][Number(r.MAGNITUD)]=values;accepted++;
 }
 if(!accepted)throw Error('Nessuna serie utilizzabile nella risposta');return records;
}
function applyRecent(payload){const fresh=parseRecent(payload);D.records=structuredClone(archiveRecords);for(const [sid,days]of Object.entries(fresh))for(const [date,series]of Object.entries(days)){if(date<=D.archiveEnd)continue;D.records[sid]??={};D.records[sid][date]={...D.records[sid][date],...series};}recentResponse=payload.responseDate||null;const dates=availableDates();recentDateMin=dates.filter(d=>d>D.archiveEnd)[0]||null;if($('date')){$('date').min=dates[0];$('date').max=dates.at(-1)}}
function mergePayloads(recent,live){const rows=new Map();for(const r of [...recent.records,...live.records]){const key=[r.PUNTO_MUESTREO,r.ANO,r.MES,r.DIA].join('|');rows.set(key,r)}const records=[...rows.values()];return{status:200,records,totalRecords:records.length,responseDate:live.responseDate||recent.responseDate}}
function changeDate(date){state.date=date;const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date());followLatest=date===today;if(followLatest)selectLatestAvailable();render()}
function selectLatestAvailable(){const days=D.records[state.station]||{};for(const date of Object.keys(days).sort().reverse()){for(let h=24;h>=1;h--)if(order.some(c=>days[date][c]?.[h-1]!=null)){state.date=date;state.hour=h;$('date').value=date;$('hour').value=h;return}}}
function updateSourceInfo(){const preliminary=state.date>D.archiveEnd;const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date());$('dataMode').textContent=preliminary?'Misure recenti · preliminari':`Archivio ${state.date.slice(0,4)}`;$('sourceBadge').textContent=preliminary?'':'Archivio';$('sourceBadge').hidden=preliminary;$('dataNotice').textContent=preliminary?`${state.date===today?'Misure del giorno':'Misure disponibili del '+state.date}. In attesa di revisione e validazione. La fonte si aggiorna ogni 20 minuti; i valori sono medie orarie.`:`Archivio orario fino al ${D.archiveEnd}. I profili storici di confronto restano 2015–2025.`;$('syncStatus').textContent=syncMessage;$('latestBtn').setAttribute('aria-pressed',String(followLatest));$('latestBtn').textContent=followLatest?'Ultime misure selezionate':'Ultime misure';if(preliminary&&state.date<today)$('dataNotice').textContent+=' Non sono misure di oggi.';localize();}
async function fetchMunicipal(url){const response=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(25000)});if(!response.ok)throw Error('Fonte non disponibile');const data=await response.json();parseRecent(data);return data;}
async function refreshRecent(){if(syncBusy)return;syncBusy=true;$('refreshBtn').disabled=true;syncMessage='Aggiornamento delle misure comunali…';updateSourceInfo();try{
 const results=await Promise.allSettled([fetchMunicipal(RECENT_URL),fetchMunicipal(LIVE_URL)]);const recent=results[0].status==='fulfilled'?results[0].value:null,live=results[1].status==='fulfilled'?results[1].value:null;
 if(!recent&&!live)throw Error('Fonte non raggiungibile');
 // Keep the cached recent days if only the daily endpoint is available.
 if(recent)window.recentCache=recent;
 const base=recent||window.recentCache;const combined=base&&live?mergePayloads(base,live):base||live;applyRecent(combined);
 syncMessage=`Fonte consultata alle ${new Date().toLocaleTimeString(uiLocale(),{hour:'2-digit',minute:'2-digit'})}. Risposta della fonte: ${recentResponse||'orario non indicato'} (ora della fonte).${!recent||!live?' Uno dei due servizi non è disponibile.':''}`;
 }catch(e){syncMessage='Aggiornamento non riuscito. Restano visibili gli ultimi dati caricati; controlla la data della misura.';}finally{syncBusy=false;$('refreshBtn').disabled=false;render();}}
async function init(){window.addEventListener('aria-language-change',()=>{if(D)render();else localize()});document.addEventListener('click',e=>{const link=e.target.closest?.('[data-guide]');if(link){e.preventDefault();openGuide(link.dataset.guide)}});try{let res=await fetch('data.json?v=18');if(!res.ok)throw Error('Dati non disponibili');D=await res.json();const annualRes=await fetch('annual-history.json?v=1');if(!annualRes.ok)throw Error('Riepiloghi annuali non disponibili');D.annualHistorical=await annualRes.json();archiveRecords=structuredClone(D.records);try{const snapshot=await fetch('recent-snapshot.json?v=12');if(snapshot.ok){const cached=await snapshot.json();window.recentCache=cached;applyRecent(cached);syncMessage='Copia salvata disponibile. Collegamento alla fonte in corso…';}}catch{}$('station').innerHTML=D.stations.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');if(!D.records[state.station])state.station=D.stations[0].id;const dates=availableDates();$('date').min=dates[0];$('date').max=dates.at(-1);if(!dates.includes(state.date))state.date=dates.at(-1);$('date').value=state.date;$('station').value=state.station;$('hour').innerHTML=Array.from({length:24},(_,i)=>`<option value="${i+1}">${String(i+1).padStart(2,'0')}:00</option>`).join('');$('hour').value=state.hour;$('station').onchange=e=>selectStation(e.target.value);$('date').onchange=e=>{if(!e.target.value||e.target.value<$('date').min||e.target.value>$('date').max){e.target.value=state.date;return}changeDate(e.target.value)};$('hour').onchange=e=>{followLatest=false;state.hour=Number(e.target.value);render()};$('annualYear').onchange=e=>{state.annualYear=e.target.value;annualSummary()};$('annualPollutant').onchange=e=>{state.annualCode=Number(e.target.value);annualSummary()};$('comparisonMode').onchange=e=>{state.profile=e.target.value!=='none';state.shared=e.target.value==='shared';render()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});$('mapLegend').innerHTML=names.map((n,i)=>`<span><i class="keydot" style="background:${colors[i]}"></i>${n}</span>`).join('')+`<span><i class="keydot" style="background:#a5aaa7"></i>Dati insufficienti</span>`;setupMap();render();$('latestBtn').onclick=()=>{followLatest=true;render();refreshRecent()};$('refreshBtn').onclick=()=>refreshRecent();refreshRecent();setInterval(()=>{if(!document.hidden)refreshRecent()},20*60*1000);$('learnLink').onclick=e=>{e.preventDefault();openGuide(state.code)};$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('download').onclick=()=>{let lines=[typeof MadridI18n!=='undefined'?MadridI18n.csvHeader():'centralina;inquinante;data;tipo_grafico;ora_o_giorno;misura_ug_m3;profilo_mediana_ug_m3;profilo_p25;profilo_p75',...chartRows.map(r=>[state.station,P[state.code].name,state.date,state.view,r.period,r.observed??'',r.median??'',r.p25??'',r.p75??''].join(';'))];let u=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n')],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=`madrid_${state.station}_${state.code}_${state.date}_${state.view}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)};}catch(e){$('latest').textContent='Caricamento non riuscito';$('chart').innerHTML='<p class="error">Non è stato possibile caricare i dati. Ricarica la pagina per riprovare.</p>';localize();console.error(e)}}init();
